// Passos 1 e 4: classe mãe com validação e bônus de funcionário comum.
class Funcionario {
  constructor(nome, salario) {
    if (typeof salario !== 'number' || salario < 0) {
      throw new Error('salario precisa ser um número não negativo');
    }
    this.nome = nome;
    this.salario = salario;
  }
  calcularBonus() {
    return this.salario * 0.1; // 10% do salário
  }
}

// Passos 2 e 3: gerente herda, inicializa com super() e estende o cálculo.
class Gerente extends Funcionario {
  constructor(nome, salario, equipe) {
    super(nome, salario); // a mãe valida e guarda nome e salario
    this.equipe = equipe; // campo novo da filha
  }
  calcularBonus() {
    // reaproveita o cálculo da mãe e acrescenta o extra de gerente
    return super.calcularBonus() + 500;
  }
}

// Passo 5: mesmo salário, regras diferentes — cada um responde do seu jeito.
const ana = new Funcionario('Ana', 5000);
const carlos = new Gerente('Carlos', 5000, 4);
console.log(ana.calcularBonus());    // imprime: 500
console.log(carlos.calcularBonus()); // imprime: 1000  (500 da mãe + 500 extra)
console.log(carlos.nome);            // imprime: Carlos  (inicializado por super)
